import{_ as r,l as i,o as e,c as s,v as t,p as n,x as l,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"关系代数","description":"","frontmatter":{"title":"关系代数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/relational-algebra.md","filePath":"cs/relational-algebra.md","lastUpdated":1789023840000}'),h={name:"cs/relational-algebra.md"};function m(E,a,_,B,A,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="关系代数" tabindex="-1">关系代数 <a class="header-anchor" href="#关系代数" aria-label="Permalink to &quot;关系代数&quot;">​</a></h1><div class="epigraph"><p>五种基本运算生成关系上的闭包；其余运算是简写，不是另一套数据模型。</p><footer>—— 据 Codd, Relational Completeness of Data Base Sublanguages, 1972 整理</footer></div><p><a href="/cs/fk-actions">上一课</a>钉死了键与参照完整性：元组可识别，引用是值。本课不重讲候选键。缺口是：有了合法的关系实例，如何从已有关系算出新关系，而不先指定扫描顺序或索引。查询需要一套对关系封闭的运算，后课 SQL 才有指称语义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文件 API 的操作是读字节、写字节。<a href="/cs/relational-model">关系</a>若只有存储没有运算，应用仍会把循环写进客户端。Codd 要的是代数：选择、投影、并、差、笛卡尔积（或自然连接）对关系封闭，复合仍是关系。缺口不是「会不会 SELECT」，而是先有可推理的表达式。</p><p>完整性已经保证运算的输入合法；代数不负责再检查外键。本课也不引入代价：同一个表达式可以对应许多物理计划，那是后课。</p><p><span class="marginnote">并与差要求并相容：属性数目与域一致。投影会去掉键，结果可能不再满足原表的实体完整性——结果是新关系，键另算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>基本运算：\\(\\sigma_\\theta(R)\\) 按谓词筛选元组；\\(\\pi_A(R)\\) 保留属性集 \\(A\\)；\\(\\cup\\)、\\(-\\) 在并相容的关系上做集合并与差；\\(R\\times S\\) 为笛卡尔积。自然连接 \\(R\\bowtie S\\) 是在共享属性上等值后投影掉重复列，可从积与选择导出。改名 \\(\\rho\\) 解决属性冲突。</p><p>除法、半连接、外连接是派生。本课锁定闭包与复合，不把外连接的 NULL 语义写完——那是 SQL 的缺口。安全的查询（不生成无限关系）在有限实例上自动满足；演算的安全限制本课不展开。</p>',10)),(e(),n(c,null,{default:l(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%85%B3%E7%B3%BB%20R%2C%20S%22%5D%20--%3E%20SIG%5B%22%E9%80%89%E6%8B%A9%20%CF%83%22%5D%0A%20%20R%20--%3E%20PI%5B%22%E6%8A%95%E5%BD%B1%20%CF%80%22%5D%0A%20%20R%20--%3E%20JOIN%5B%22%E8%BF%9E%E6%8E%A5%20%E2%8B%88%22%5D%0A%20%20SIG%20--%3E%20Q%5B%22%E4%BB%8D%E6%98%AF%E5%85%B3%E7%B3%BB%22%5D%0A%20%20PI%20--%3E%20Q%0A%20%20JOIN%20--%3E%20Q%0A%20%20Q%20--%3E%20SQL%5B%22%E5%90%8E%E8%AF%BE%3A%20SQL%20%E5%A3%B0%E6%98%8E%E6%80%A7%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代数表达式是树：叶是命名关系，内节点是运算。等价的树表示同一映射，这是后课改写的对象。选择与投影可下推到叶，是因为它们与连接交换（在无副作用、集合语义下）。键在运算中的去向可以静态看：连接保留键的组合条件，投影可能丢掉键。</p><p>集合语义下 \\(\\pi\\) 要去重。包语义（SQL 默认）把去重变成可选项，代数律仍大致可用，但基数估计必须改——后课代价估计才碰。本课按集合讲，避免第一课代数就陷入 NULL 与包。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 SQL 教程，不写嵌套子查询，不引入聚合与分组。分组破坏「结果是元组集合、属性来自输入」的简单图像，是后课声明语言的扩展。也不把代数当成必须由人手工执行的计划：物理算子在<a href="/cs/join-algorithms">连接算法</a>。</p><p>后课默认：谈到查询的含义，先有一棵代数树；SQL 是这棵树的写法，不是另一套模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>键已在；本课给出关系上封闭的运算与复合。</li><li>选择、投影、并、差、积（连接）是骨架；其余是简写。</li><li>表达式树是后课优化的对象，本课不谈代价。</li><li>出处：Codd, 1970 与 1972；Garcia-Molina, Ullman and Widom, <em>Database Systems: The Complete Book</em>。</li></ul>',8))])}const b=r(h,[["render",m]]);export{f as __pageData,b as default};
